CREATE TABLE public.sys_audit (
    sys_id uuid DEFAULT gen_random_uuid() NOT NULL,
    table_name character varying(80) NOT NULL,
    document_id uuid NOT NULL,
    operation character varying(6) NOT NULL,
    field_name character varying(80) NOT NULL,
    old_value jsonb,
    new_value jsonb,
    changed_on timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    changed_by uuid NOT NULL,
    CONSTRAINT sys_audit_operation_check CHECK (((operation)::text = ANY ((ARRAY['INSERT'::character varying, 'UPDATE'::character varying, 'DELETE'::character varying])::text[])))
);


