--

CREATE TABLE public.sys_number (
    sys_id uuid DEFAULT gen_random_uuid() NOT NULL,
    table_id uuid NOT NULL,
    field_name character varying(80) DEFAULT 'number'::character varying NOT NULL,
    prefix character varying(3) NOT NULL,
    minimum_digits smallint DEFAULT 7 NOT NULL,
    start_number bigint DEFAULT 1 NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    sys_created_on timestamp with time zone DEFAULT clock_timestamp(),
    sys_updated_on timestamp with time zone DEFAULT clock_timestamp(),
    sys_created_by uuid,
    sys_updated_by uuid,
    sys_mod_count integer DEFAULT 0 NOT NULL,
    CONSTRAINT sys_number_minimum_digits_check CHECK (((minimum_digits >= 1) AND (minimum_digits <= 19))),
    CONSTRAINT sys_number_prefix_check CHECK ((((char_length((prefix)::text) >= 1) AND (char_length((prefix)::text) <= 3)) AND ((prefix)::text = upper(btrim((prefix)::text))))),
    CONSTRAINT sys_number_start_number_check CHECK ((start_number >= 1))
);


