    field_name character varying(80),
    action_name character varying(100),
    condition_tree jsonb,
    is_active boolean DEFAULT true NOT NULL,
    sys_created_on timestamp with time zone DEFAULT clock_timestamp(),
    sys_updated_on timestamp with time zone DEFAULT clock_timestamp(),
    sys_created_by uuid,
    sys_updated_by uuid,
    sys_mod_count integer DEFAULT 0 NOT NULL,
    CONSTRAINT sys_permission_check CHECK (((field_name IS NULL) OR ((operation)::text = ANY ((ARRAY['create'::character varying, 'read'::character varying, 'update'::character varying])::text[])))),
    CONSTRAINT sys_permission_check1 CHECK (((((operation)::text = 'execute'::text) AND (action_name IS NOT NULL) AND (field_name IS NULL)) OR (((operation)::text <> 'execute'::text) AND (action_name IS NULL)))),
    CONSTRAINT sys_permission_operation_check CHECK (((operation)::text = ANY ((ARRAY['create'::character varying, 'read'::character varying, 'update'::character varying, 'delete'::character varying, 'execute'::character varying])::text[])))
);


