    CONSTRAINT sys_script_action_type_check CHECK (((action_type)::text = ANY ((ARRAY['set_field_value'::character varying, 'abort_transaction'::character varying, 'execute_script'::character varying])::text[]))),
    CONSTRAINT sys_script_execution_mode_check CHECK (((execution_mode)::text = ANY ((ARRAY['caller'::character varying, 'service'::character varying])::text[]))),
    CONSTRAINT sys_script_timing_check CHECK (((timing)::text = ANY ((ARRAY['before_insert'::character varying, 'before_update'::character varying, 'after_insert'::character varying, 'after_update'::character varying])::text[])))
);


--
-- Name: sys_state; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sys_state (
    sys_id uuid DEFAULT gen_random_uuid() NOT NULL,
    table_id uuid,
    name character varying(80) NOT NULL,
    label character varying(100) NOT NULL,
    sequence integer DEFAULT 0 NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    color character varying(40) DEFAULT 'gray'::character varying,
    description text,
    sys_created_on timestamp with time zone DEFAULT clock_timestamp(),
    sys_updated_on timestamp with time zone DEFAULT clock_timestamp(),
    sys_created_by uuid,
    sys_updated_by uuid,
    sys_mod_count integer DEFAULT 0 NOT NULL
);


--
