CREATE TABLE public.sys_state_transition (
    sys_id uuid DEFAULT gen_random_uuid() NOT NULL,
    table_id uuid NOT NULL,
    state_field character varying(80) DEFAULT 'state'::character varying NOT NULL,
    from_state character varying(50) NOT NULL,
    to_state character varying(50) NOT NULL,
    label character varying(80) NOT NULL,
    required_role_id uuid,
    condition_tree jsonb,
    on_transition_action jsonb,
    is_active boolean DEFAULT true NOT NULL,
    sys_created_on timestamp with time zone DEFAULT clock_timestamp(),
    sys_updated_on timestamp with time zone DEFAULT clock_timestamp(),
    sys_created_by uuid,
    sys_updated_by uuid,
    sys_mod_count integer DEFAULT 0 NOT NULL,
    from_state_id uuid NOT NULL,
    to_state_id uuid NOT NULL
);


