    sys_created_on timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    sys_created_by uuid NOT NULL,
    sys_updated_on timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    sys_updated_by uuid NOT NULL,
    sys_mod_count integer DEFAULT 0 NOT NULL,
    short_description character varying(160),
    number character varying(22) NOT NULL,
    state uuid DEFAULT '30000000-0000-0000-0000-000000000002'::uuid
);


--
-- Name: v_incident; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_incident AS
 SELECT t1.sys_id,
    t1.sys_class_name,
    t1.sys_created_on,
    t1.sys_created_by,
    t1.sys_updated_on,
    t1.sys_updated_by,
    t1.sys_mod_count,
    t1.short_description,
    t1.state,
    t1.number,
    t0.severity,
    t0.close_notes
   FROM (public.tbl_incident t0
     JOIN public.tbl_task t1 ON ((t0.sys_id = t1.sys_id)));


--
-- Name: v_task; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_task AS
 SELECT sys_id,
    sys_class_name,
    sys_created_on,
    sys_created_by,
    sys_updated_on,
    sys_updated_by,
    sys_mod_count,
    short_description,
    number,
    state
   FROM public.tbl_task;


